{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C65"],
      "claim": "In healthy volunteers, the absolute oral bioavailability of GSK1322322, a lipophilic heteroaromatic drug, was 77% in the fed state and 57% in the fasted state, directly demonstrating high F despite challenging physicochemical properties.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Glasdegib, a lipophilic heteroaromatic kinase inhibitor, had an absolute oral bioavailability of 77.12% in healthy volunteers after a 100 mg oral dose compared with IV, supporting high F for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Ivosidenib, a lipophilic heteroaromatic drug, showed 57.2% absolute oral bioavailability in healthy subjects under fasting conditions, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Vorinostat (SAHA), the lowest-F analogue in the set, still had 43% absolute oral bioavailability in humans, indicating that even the least favorable measured case exceeds the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer human absolute bioavailability data for structurally related lipophilic heteroaromatic drugs are consistently above 40%, far exceeding the 20% threshold. The query's favorable permeability and absence of hydrogen-bond donors support high oral bioavailability, with solubility as the main residual uncertainty.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "Solubility and dissolution at clinically relevant doses are not experimentally characterized.",
    "First-pass metabolism and transporter-mediated efflux are not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

